package com.acme.member.renewal;

import org.springframework.stereotype.Component;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;

/**
 * 支付回调验签骨架（RED 阶段）：仅声明新协议 API，行为尚未实现。
 */
@Component
public class SignatureVerifier {

    static final String DEVELOPMENT_SECRET = "dev-secret-do-not-use-in-prod";

    private Clock clock = Clock.systemUTC();
    private String secret = DEVELOPMENT_SECRET;
    private String legacySecret = DEVELOPMENT_SECRET;
    private boolean legacyEnabled = true;
    private long timestampToleranceSeconds = 300L;

    public SignatureVerifier() {
    }

    SignatureVerifier(Clock clock, String secret, String legacySecret,
                      boolean legacyEnabled, long timestampToleranceSeconds) {
        this.clock = clock;
        this.secret = secret;
        this.legacySecret = legacySecret;
        this.legacyEnabled = legacyEnabled;
        this.timestampToleranceSeconds = timestampToleranceSeconds;
    }

    public boolean verify(String externalTxnId, long amountCents, String signature) {
        if (signature == null || signature.isBlank()) {
            return false;
        }
        return sign(externalTxnId, amountCents).equalsIgnoreCase(signature);
    }

    public String sign(String externalTxnId, long amountCents) {
        String payload = externalTxnId + ":" + amountCents + ":" + legacySecret;
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashed = digest.digest(payload.getBytes(StandardCharsets.UTF_8));
            StringBuilder builder = new StringBuilder(hashed.length * 2);
            for (byte value : hashed) {
                builder.append(Character.forDigit((value >> 4) & 0xF, 16));
                builder.append(Character.forDigit(value & 0xF, 16));
            }
            return builder.toString();
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("MD5 不可用", exception);
        }
    }

    public String signV2(String externalTxnId, long amountCents, long timestamp) {
        return "v2:";
    }

    public boolean verify(String externalTxnId, long amountCents, Long timestamp, String signature) {
        return false;
    }
}

