package com.acme.member.renewal;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * RED 探针：新协议 API 尚未实现，测试明确失败。
 * 实现完成后本文件替换为完整的 SignatureV2Test 验收用例。
 */
class SignatureV2Test {

    @Test
    void newProtocolApiIsNotImplementedYet() throws Exception {
        Clock fixedClock = Clock.fixed(Instant.parse("2025-12-01T00:00:00Z"), ZoneOffset.UTC);
        Constructor<SignatureVerifier> constructor = SignatureVerifier.class.getDeclaredConstructor(
                Clock.class, String.class, String.class, boolean.class, long.class);
        constructor.setAccessible(true);
        SignatureVerifier verifier = constructor.newInstance(
                fixedClock, "test-secret-A", "dev-secret-do-not-use-in-prod", true, 300L);

