package com.acme.member.renewal;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.Instant;
import java.util.Locale;

/**
 * 支付回调验签。
 *
 * <p>同时支持两种协议：
 * <ul>
 *   <li>旧协议：{@code MD5(流水号:金额:legacy-secret)}，可由 {@code renewal.callback.legacy-enabled}
 *       一键关闭；</li>
 *   <li>新协议：{@code v2:} 前缀 + {@code HMAC-SHA256(流水号:金额:时间戳)}，时间戳为 UTC epoch 秒，
 *       与服务器时间偏差不得超过 {@code renewal.callback.timestamp-tolerance-seconds}。</li>
 * </ul>
 *
 * <p>密钥全部来自配置，代码中不再包含生产密钥；签名比较统一走常量时间比较。
 * 新协议验签失败不会回退到旧协议，避免攻击者用坏时间戳触发降级。
 */
@Component
public class SignatureVerifier {

    /** 仅用于本地开发/测试的默认值，生产必须通过环境变量覆盖。 */
    static final String DEVELOPMENT_SECRET = "dev-secret-do-not-use-in-prod";

    private static final String V2_PREFIX = "v2:";
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final char[] HEX_DIGITS = "0123456789abcdef".toCharArray();

    private Clock clock = Clock.systemUTC();

    @Value("${renewal.callback.secret:" + DEVELOPMENT_SECRET + "}")
    private String secret = DEVELOPMENT_SECRET;

    @Value("${renewal.callback.legacy-secret:" + DEVELOPMENT_SECRET + "}")
    private String legacySecret = DEVELOPMENT_SECRET;

    @Value("${renewal.callback.legacy-enabled:true}")
    private boolean legacyEnabled = true;

    @Value("${renewal.callback.timestamp-tolerance-seconds:300}")
    private long timestampToleranceSeconds = 300L;

    public SignatureVerifier() {
    }

    /**
     * 包级构造供纯 JUnit 测试注入固定时钟与测试密钥，不启动 Spring。
     */
    SignatureVerifier(Clock clock, String secret, String legacySecret,
                      boolean legacyEnabled, long timestampToleranceSeconds) {
        this.clock = clock == null ? Clock.systemUTC() : clock;
        this.secret = secret;
        this.legacySecret = legacySecret;
        this.legacyEnabled = legacyEnabled;
        this.timestampToleranceSeconds = timestampToleranceSeconds;
    }

    @Autowired(required = false)
    void setClock(Clock clock) {
        if (clock != null) {
            this.clock = clock;
        }
    }

    /**
     * 旧入口：固定按旧 MD5 协议校验，保持历史调用方语义不变。
     */
    public boolean verify(String externalTxnId, long amountCents, String signature) {
        if (signature == null || signature.isBlank()) {
            return false;
        }
        return verifyLegacy(externalTxnId, amountCents, signature);
    }

    /**
     * 新入口：按 {@code v2:} 前缀分流，新协议失败不回退旧协议。
     */
    public boolean verify(String externalTxnId, long amountCents, Long timestamp, String signature) {
        if (signature == null || signature.isBlank()) {
            return false;
        }
        if (signature.startsWith(V2_PREFIX)) {
            return verifyV2(externalTxnId, amountCents, timestamp,
                    signature.substring(V2_PREFIX.length()));
        }
        return verifyLegacy(externalTxnId, amountCents, signature);
    }

    /**
     * 旧协议签名：{@code MD5(流水号:金额:legacy-secret)}，输出小写 hex。
     */
    public String sign(String externalTxnId, long amountCents) {
        return md5Hex(legacyPayload(externalTxnId, amountCents));
    }

    /**
     * 新协议签名：{@code v2:} 前缀 + HMAC-SHA256(流水号:金额:时间戳)，输出小写 hex。
     */
    public String signV2(String externalTxnId, long amountCents, long timestamp) {
        return V2_PREFIX + hmacHex(secret, v2Payload(externalTxnId, amountCents, timestamp));
    }

    private boolean verifyV2(String externalTxnId, long amountCents, Long timestamp, String providedHex) {
        if (timestamp == null || isBlank(secret)) {
            return false;
        }
        long now = Instant.now(clock).getEpochSecond();
        long tolerance = Math.max(0L, timestampToleranceSeconds);
        if (timestamp > now + tolerance || timestamp < now - tolerance) {
            return false;
        }
        String expected = hmacHex(secret, v2Payload(externalTxnId, amountCents, timestamp));
        return constantTimeHexEquals(expected, providedHex);
    }

    private boolean verifyLegacy(String externalTxnId, long amountCents, String providedHex) {
        if (!legacyEnabled || isBlank(legacySecret)) {
            return false;
        }
        String expected = md5Hex(legacyPayload(externalTxnId, amountCents));
        return constantTimeHexEquals(expected, providedHex);
    }

    private String legacyPayload(String externalTxnId, long amountCents) {
        return externalTxnId + ":" + amountCents + ":" + legacySecret;
    }

    private static String v2Payload(String externalTxnId, long amountCents, long timestamp) {
        return externalTxnId + ":" + amountCents + ":" + timestamp;
    }

    private static boolean constantTimeHexEquals(String expectedLowerHex, String providedHex) {
        byte[] expected = expectedLowerHex.getBytes(StandardCharsets.US_ASCII);
        byte[] provided = providedHex.toLowerCase(Locale.ROOT).getBytes(StandardCharsets.US_ASCII);
        return MessageDigest.isEqual(expected, provided);
    }

    private static String md5Hex(String payload) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            return toHex(digest.digest(payload.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("MD5 不可用", exception);
        }
    }

    private static String hmacHex(String key, String payload) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            mac.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM));
            return toHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));
        } catch (GeneralSecurityException exception) {
            throw new IllegalStateException("HMAC-SHA256 不可用", exception);
        }
    }

    private static String toHex(byte[] bytes) {
        char[] chars = new char[bytes.length * 2];
        for (int i = 0; i < bytes.length; i++) {
            int value = bytes[i] & 0xFF;
            chars[i * 2] = HEX_DIGITS[value >>> 4];
            chars[i * 2 + 1] = HEX_DIGITS[value & 0x0F];
        }
        return new String(chars);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

